from pathlib import Path
import base64

DATA = '''[... ELLIPSIZATION ...]AAC=='''

# Replace the temporary vector icon with the actual approved rendered artwork.
xml = Path('app/src/main/res/drawable/app_icon.xml')
if xml.exists():
    xml.unlink()
out = Path('app/src/main/res/drawable-nodpi/app_icon.webp')
out.parent.mkdir(parents=True, exist_ok=True)
out.write_bytes(base64.b64decode(DATA))
print('Installed v19 rendered app icon')
